    title:
      'DNA Mixture Interpretation: A NIST Scientific Foundation Review (NISTIR 8351), final report, December 2024',
    publisher: 'National Institute of Standards and Technology (United States)',
    url: 'https://nvlpubs.nist.gov/nistpubs/ir/2024/NIST.IR.8351.pdf',
